var params = JSON.parse(value);

var url = params.url.replace(/\/+$/, '');
var token = (params.token || '').trim();
var environmentId = String(params.environment_id || '').trim();
var environmentName = String(params.environment_name || '').trim();

if (environmentId === '') {
    throw 'Dockhand environment ID is empty';
}

var request = new HttpRequest();

if (token !== '') {
    request.addHeader('Authorization: Bearer ' + token);
}

var endpoint =
    url +
    '/api/containers?env=' +
    encodeURIComponent(environmentId) +
    '&all=true';

var response = request.get(endpoint);
var status = request.getStatus();

if (status < 200 || status >= 300) {
    throw 'Dockhand API returned HTTP ' + status +
        ' for environment "' + environmentName +
        '" (' + environmentId + '): ' + response;
}

var data;

try {
    data = JSON.parse(response);
}
catch (e) {
    throw 'Invalid JSON returned by Dockhand /api/containers for environment "' +
        environmentName + '": ' + e;
}

if (!Array.isArray(data)) {
    throw 'Dockhand /api/containers did not return an array for environment "' +
        environmentName + '"';
}

var result = [];

for (var i = 0; i < data.length; i++) {
    var container = data[i];
    var labels = container.labels || {};

    var notifyLabel = labels['dockhand.notify'];

    if (
        notifyLabel !== undefined &&
        String(notifyLabel).toLowerCase() === 'false'
    ) {
        continue;
    }

    var stack = labels['com.docker.compose.project'] || '';
    var service = labels['com.docker.compose.service'] || '';

    result.push({
        environment_id: environmentId,
        environment_name: environmentName,
        container_id: container.id || '',
        container_name: container.name || '',
        image: container.image || '',
        state: container.state || 'unknown',
        status: container.status || '',
        health: container.health || '',
        restart_count:
            container.restartCount !== undefined
                ? Number(container.restartCount)
                : 0,
        stack: stack,
        service: service
    });
}

return JSON.stringify(result);

