var params = JSON.parse(value);

var url = String(params.url || '').replace(/\/+$/, '');
var token = String(params.token || '').trim();
var environmentId = String(params.environment_id || '').trim();
var environmentName = String(params.environment_name || '').trim();
var containerName = String(params.container_name || '').trim();

if (url === '') {
    throw 'Dockhand URL is empty';
}

if (environmentId === '') {
    throw 'Dockhand environment ID is empty';
}

if (containerName === '') {
    throw 'Dockhand container name is empty';
}

var request = new HttpRequest();

if (token !== '') {
    request.addHeader('Authorization: Bearer ' + token);
}

var endpoint =
    url +
    '/api/containers/' +
    encodeURIComponent(containerName) +
    '/inspect?env=' +
    encodeURIComponent(environmentId);

var response = request.get(endpoint);
var status = request.getStatus();

if (status < 200 || status >= 300) {
    throw 'Dockhand API returned HTTP ' + status +
        ' while inspecting container "' + containerName +
        '" from environment "' + environmentName + '": ' + response;
}

var container;

try {
    container = JSON.parse(response);
}
catch (e) {
    throw 'Invalid JSON returned by Dockhand container inspect API: ' + e;
}

var labels =
    container.Config && container.Config.Labels
        ? container.Config.Labels
        : {};

var state = container.State || {};
var health =
    state.Health && state.Health.Status
        ? state.Health.Status
        : 'none';

var image =
    container.Config && container.Config.Image
        ? container.Config.Image
        : '';

var actualName = String(container.Name || containerName).replace(/^\/+/, '');

var humanStatus = state.Status || 'unknown';

if (state.Status === 'exited') {
    humanStatus = 'Exited (' + String(state.ExitCode) + ')';
}
else if (state.Status === 'running') {
    humanStatus = health !== 'none'
        ? 'Running (' + health + ')'
        : 'Running';
}
else if (state.Status === 'restarting') {
    humanStatus = 'Restarting';
}

return JSON.stringify({
    environment_id: environmentId,
    environment_name: environmentName,

    stack: labels['com.docker.compose.project'] || '',
    service: labels['com.docker.compose.service'] || '',

    container_name: actualName,
    container_id: container.Id || '',

    image: image,
    state: state.Status || 'unknown',
    status: humanStatus,
    health: health,

    restart_count:
        container.RestartCount !== undefined
            ? Number(container.RestartCount)
            : 0,

    exit_code:
        state.ExitCode !== undefined
            ? Number(state.ExitCode)
            : null,

    created:
        container.Created
            ? Math.floor(Date.parse(container.Created) / 1000)
            : null
});

